CREATE OR REPLACE FUNCTION ECAMS.EXE_CHECK
(RSRCNAME varchar2,NOEXENAME varchar2)
return VARCHAR2
IS
    V_WORK1     VARCHAR2(4000);
    V_WORK2     VARCHAR2(4000);
BEGIN
    IF INSTR(RSRCNAME,'.') = 0 THEN
       RETURN 'Y';
    END IF;


    V_WORK2 := RSRCNAME;
    LOOP
        IF INSTR(V_WORK2,'.') > 0 THEN
            V_WORK2 := SUBSTR(V_WORK2,INSTR(V_WORK2,'.')+1);
        ELSE
           EXIT;
        END IF;
    END LOOP;

    V_WORK1 := ',.' || V_WORK2 || ',';

    V_WORK2 := ',' || NOEXENAME || ',';
    IF INSTR(V_WORK2,V_WORK1) > 0 THEN
       RETURN 'N';
    ELSE
       RETURN 'Y';
    END IF;
    return V_WORK1;
END ;